using System;using System.Linq;using UnityEngine;
public static class RemainingCameraAudit {public static object Run()=>new{cameras=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Include,FindObjectsSortMode.None).Select(c=>new{c.name,c.enabled,active=c.gameObject.activeInHierarchy,parent=c.transform.parent?c.transform.parent.name:null,position=c.transform.position.ToString(),rotation=c.transform.eulerAngles.ToString(),c.tag}),looks=UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(c=>c.GetType().Name=="PlayerLook").Select(c=>new{name=c.name,fields=c.GetType().GetFields(System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Select(f=>new{f.Name,type=f.FieldType.Name,value=Convert.ToString(f.GetValue(c))})})};}
